const getValueByPath = (tree: TranslationTree, path: string): string | undefined => {
  const segments = path.split('.')
  let current: TranslationLeaf | TranslationTree | undefined = tree

  for (const segment of segments) {
    if (!current || typeof current === 'string') {
      return undefined
    }
    current = current[segment]
  }

  return typeof current === 'string' ? current : undefined
}

const replaceParams = (template: string, params?: Record<string, string | number>) =>
  template.replace(/\{(\w+)\}/g, (_, key: string) => String(params?.[key] ?? ''))

export const translate = (language: LanguageCode, key: string, params?: Record<string, string | number>) => {
  const template =
    getValueByPath(translations[language], key) ||
    getValueByPath(translations.en, key) ||
    key

  return replaceParams(template, params)
}

export const useI18n = () => {
  const language = useLanguageStore((state) => state.language)
  const setLanguage = useLanguageStore((state) => state.setLanguage)

  return {
    language,
    setLanguage,
    t: (key: string, params?: Record<string, string | number>) => translate(language, key, params),
  }
}
